// ── Helpers ──

function createImage(op, mode) {
    const size = [30, 30];
    switch (mode) {
        case 'L': return new wasm.Image('L', size[0], size[1], 128, 128, 128, 255);
        case 'LA': return new wasm.Image('LA', size[0], size[1], 128, 128, 128, 255);
        case 'RGB': return new wasm.Image('RGB', size[0], size[1], 255, 0, 0, 255);
        case 'RGBA': return new wasm.Image('RGBA', size[0], size[1], 255, 0, 0, 255);
        case '1': return new wasm.Image('1', size[0], size[1], 1, 1, 1, 255);
        case 'P': return new wasm.Image('RGB', size[0], size[1], 255, 0, 0, 255);
        case 'CMYK':
        case 'YCbCr':
        case 'HSV':
        case 'I':
        case 'F': return new wasm.Image('RGB', size[0], size[1], 255, 0, 0, 255);
        default: return new wasm.Image('RGB', size[0], size[1], 255, 0, 0, 255);
    }
}

function runOp(img, op) {
    const [_, func] = op.split('.');
    switch (func) {
        case 'resize': return img.resize(15, 15);
        case 'crop': return img.crop(5, 5, 25, 25);
        case 'rotate': return img.rotate(90);
        case 'transpose': return img.transpose('FLIP_LEFT_RIGHT');
        case 'filter': return img.filter('BLUR');
        case 'convert': return img.convert('RGB');
        case 'copy': return img.copy();
        case 'thumbnail': img.thumbnail(15, 15); return img;
        case 'quantize': return img.quantize(16);
        case 'tobytes': return img.toBytes();
        default: return img;
    }
}
